def verifier(assign):
    b1 = assign['b1']
    b2 = assign['b2']
    d1 = assign['d1']
    d2 = assign['d2']

    # Constraint: must be a valid trapezoid with intersecting non-parallel sides
    if b1 <= b2:
        return False, None # AB must be the longer base

    k = b1 - b2
    # Triangle inequality for the triangle formed by sides d1, d2, and k
    if not (d1 + d2 > k and d1 + k > d2 and d2 + k > d1):
        return False, None # Not a valid trapezoid geometry

    # The ratio AP/PC is given by (b1*d1) / (b2*d2)
    m_num = b1 * d1
    n_den = b2 * d2

    common_divisor = gcd(m_num, n_den)
    m = m_num // common_divisor
    n = n_den // common_divisor

    # Check if the calculated m, n match the hidden values from generator
    if 'm' in assign and 'n' in assign:
